{
  "hypotheses": [
    {
      "id": "H1",
      "mechanism": "The controller frequency is too high relative to the natural pendulum frequency of the shorter legs, causing overly rapid stepping and instability.",
      "evidence": [
        "baseline.controller_freq_ratio",
        "baseline.step_freq_hz",
        "baseline.froude",
        "baseline.forward_fall_frac"
      ],
      "competing": [
        "The frequency might be appropriate but the stride amplitudes are too small, causing small steps and inability to maintain speed."
      ]
    },
    {
      "id": "H2",
      "mechanism": "The foot placement feedback gains (fp_kd, fp_kv) are zero, causing the foot to land behind the capture point (negative capture margin) and leading to forward falls.",
      "evidence": [
        "baseline.capture_margin_over_leg_mean",
        "baseline.capture_margin_over_leg_min",
        "baseline.touchdown_foot_ahead_over_leg_mean"
      ],
      "competing": [
        "The capture margin could be negative due to incorrect stride amplitudes or timing, not necessarily placement feedback."
      ]
    },
    {
      "id": "H3",
      "mechanism": "The body parameters (shorter legs, higher mass, lower friction) differ significantly from the reference body, and the transferred controller has not been rescaled by dynamic similarity.",
      "evidence": [
        "creature.features.L",
        "creature.reference.features.L",
        "creature.features.mass_total",
        "creature.reference.features.mass_total",
        "creature.features.friction",
        "creature.reference.features.friction",
        "creature.features.tau_ratio",
        "creature.reference.features.tau_ratio"
      ],
      "competing": [
        "The controller might be adaptable via feedback gains without needing full rescaling."
      ]
    }
  ],
  "probes": [
    {
      "probe_id": "similarity",
      "hypothesis": "H3",
      "expect": "improves"
    },
    {
      "probe_id": "opt_placement",
      "hypothesis": "H2",
      "expect": "improves"
    },
    {
      "probe_id": "opt_timing",
      "hypothesis": "H1",
      "expect": "improves"
    }
  ]
}

