  "hypotheses": [
    {
      "id": "H4",
      "mechanism": "The stride amplitudes (hip_amp, knee_amp) are too small, resulting in short step length (baseline.step_length_over_leg=0.1696) and low Froude number (0.03441), limiting speed maintenance and robustness.",
      "evidence": [
        "baseline.step_length_over_leg",
        "baseline.froude",
        "baseline.speed_trend_mps2"
      ],
      "competing": [
        "The short steps could be due to high frequency or incorrect timing, not amplitude."
      ]
    },
    {
      "id": "H5",
      "mechanism": "The feedback gains (kp, kd, balance_gain, pitch_kp, sync_gain) are not well tuned for this body, leading to insufficient disturbance rejection and forward pitch drift (baseline.pitch_drift_radps=0.04965).",
      "evidence": [
        "baseline.pitch_drift_radps",
        "baseline.pitch_mean_rad",
        "baseline.peak_tau_over_limit_hip",
        "baseline.peak_tau_over_limit_knee",
        "baseline.peak_tau_over_limit_ankle"
      ],
      "competing": [
        "The pitch drift could be caused by incorrect posture references or placement."
      ]
    },
    {
      "id": "H6",
      "mechanism": "The posture parameters (hip_bias, pitch_ref, stance_knee, start_lean) are not appropriate for this body, causing forward lean (baseline.pitch_mean_rad=0.1584, baseline.pitch_at_end_rad=0.9875) and forward falls.",
      "evidence": [
        "baseline.pitch_mean_rad",
        "baseline.pitch_at_end_rad",
        "baseline.forward_fall_frac"
